import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>亮度是最简单的修图操作，也是大家最先想到的办法。偏暗的照片变清楚了，发灰的照片有了层次，平淡的照片又活了过来。</p>\n<p>但亮度很容易调过头。推得太远，照片会变得又平又灰，高光部分一片死白，细节全没了。</p>\n<p>这篇指南会讲清亮度是怎么起作用的、滑块和预设怎么用好、暗照片怎么修才不毁图。内容包括人像、风景、截图，以及最容易毁掉好照片的几个错误。边读边练最有效，<a href=\"/zh/tiaozheng-tupian-liangdu/\">图片亮度调节</a>可以实时对比预览，调亮或调暗都能立刻看到效果。</p>\n<h2 id=\"what-brightness-does\">亮度到底改变了什么</h2>\n<p>亮度是把图片里的每个像素一起往白或者往黑推。调高，暗部变亮、亮部更亮；调低，整张图一起变暗。</p>\n<p>这个变化是整张图均匀的。亮度不会单独挑出阴影或者高光，它是把整个色调范围一起上下移动。</p>\n<p>均匀既是亮度的优点，也是它的短板。整张偏暗或者偏亮的照片，用亮度修最快；但一张图一半暗一半亮，亮度就修不好了。</p>\n<p>可以把亮度想成房间里的灯。灯调亮调暗，屋里所有东西一起变亮变暗，东西之间的相对差别保持不变。</p>\n<h2 id=\"why-photos-are-dark\">照片为什么会拍暗</h2>\n<p>手机在复杂光线下经常曝光不足。人身后是明亮的天空、背景里有窗户、或者有个很强的光源，相机都可能被骗得把主体拍暗。</p>\n<p>室内照片偏暗的原因更简单：光不够。一盏灯照亮的房间，光线比室外少得多，照片自然就暗。</p>\n<p>扫描件和老照片也常常偏暗。年代久了相纸褪色，扫描仪读不准色调，结果就是一张灰蒙蒙、脏兮兮的图，需要提亮。</p>\n<p>截图偏暗，往往是因为屏幕本身就很暗。拍屏幕的照片，或者屏幕亮度调低时截的图，都需要提亮才看得清。</p>\n<h2 id=\"brightening-vs-exposure\">提亮和曝光是一回事吗</h2>\n<p>亮度和曝光有关，但不是同一个东西。曝光是相机拍到了多少光，亮度是拍下来的像素显示出来有多亮。</p>\n<p>在编辑器里，两个控制用起来感觉差不多，因为都能让图片变亮或者变暗。差别在于它们对待色调两端的方式不一样。</p>\n<p>曝光调整对高光和阴影的影响不一样，能在两端保留更多细节。亮度是均匀移动所有像素，所以亮部更容易先被洗白。</p>\n<p>在浏览器编辑器里做快速修正，亮度就是合适的工具。简单、可预测、速度快，大多数照片用它就能修到想要的效果。</p>\n<h2 id=\"slider-explained\">亮度滑块讲清楚</h2>\n<p>亮度滑块从负值到正值，0 就是不改。往右拖变亮，往左拖变暗。</p>\n<p>小幅度移动，效果就很明显。10% 到 15% 的变化常常就够修好一张偏暗的照片，再往上推，高光很快就会被洗白。</p>\n<p>上传照片后，工具会先把预览设在 +15%。这个起点能让你立刻看到中等程度提亮是什么样子。</p>\n<p>拖滑块时慢一点，看着预览调。实时预览能准确显示图片的变化，觉得顺眼了就停下来。</p>\n<h2 id=\"quick-presets\">一键修正的快捷预设</h2>\n<p>工具里有快捷预设，点一下就能套用常用的亮度值。不用拖滑块，就能快速试几个不同的亮度。</p>\n<p>预设是起点，不是最终答案。点一个预设，看一眼预览，觉得接近但还差一点，就用滑块再微调。</p>\n<p>用预设对比很方便。+15% 和 +30% 的预设放一起看，立刻就知道这张照片能承受多少提亮、什么时候开始发灰。</p>\n<p>一批类似的照片，用同一个预设能保持一致。一组室内暗照都提亮同样的幅度，看着就像一个系列。</p>\n<h2 id=\"compare-modes\">对比模式：原图、效果图和分屏</h2>\n<p>对比模式能把原图和修好的图放在一起看。“效果图”显示提亮后的样子，“原图”显示没修的样子，“分屏”左右对照。</p>\n<p>调亮度时，分屏对比最有用。中间一条线隔开两边，哪些地方变好了、哪些地方被洗白了，一眼就能看出来。</p>\n<p>全屏对比的画面最大。判断提亮效果时最好用全屏，因为全尺寸图片才能显示小预览里藏起来的细节。</p>\n<p>“按住查看原图”适合快速检查。按住看原图，松开看修好的图，两者的差别立刻就明显了。</p>\n<h2 id=\"brightening-portraits\">人像怎么提亮</h2>\n<p>人像提亮要轻。脸太暗，眼睛和表情都藏住了；脸太亮，皮肤质感没了，看着又平又假。</p>\n<p>先加 10% 到 15%，看一眼肤色。人脸应该看着是自然受光，而不是像近距离打了闪光灯。</p>\n<p>盯住额头和鼻子的高光。这两个地方最先过曝，脸上出现白色斑块的提亮图，还不如偏暗的原图好看。</p>\n<p>逆光人像只靠提亮可能不够。人脸和背景需要的处理不一样，亮度只能把两者一起移动，顾此失彼。</p>\n<h2 id=\"brightening-landscapes\">风景照怎么提亮</h2>\n<p>风景照常常是阴影要提亮、天空已经很亮。整体提亮会把天空洗白，前景是修好了，天空却没了。</p>\n<p>用中等幅度提亮，先看天空。云朵失去形状、变成一片死白，就是推过头了。</p>\n<p>前景暗、天空亮的风景，轻轻提亮，接受一点折中。目标是一张均衡的照片，不是一张完美的照片。</p>\n<p>清晨和傍晚的照片最适合提亮。低角度的光线色彩浓郁，轻轻一提，细节出来了，氛围还在。</p>\n<h2 id=\"brightening-screenshots\">截图和文档怎么提亮</h2>\n<p>截图和扫描文档比照片需要更大胆的提亮。文字必须看得清，灰底灰字的暗扫描根本没法用。</p>\n<p>直接用 Ctrl+V 粘贴截图，省掉先保存再上传的步骤。图片立刻出现在编辑器里，就可以提亮。</p>\n<p>一直加亮度，直到文字清晰、背景变白。白底黑字的文档，又好读又好打印。</p>\n<p>留意暗部的噪点。提亮过猛的截图会出现淡淡的块状纹理，尤其是在已经压缩过的 JPEG 上。</p>\n<h2 id=\"darkening-photos\">什么时候该调暗，而不是提亮</h2>\n<p>照片过曝时，调暗才有用。又亮又平、没有阴影的照片，用负亮度能找回深度和对比。</p>\n<p>太亮的照片用 -15% 或者 -30% 这样的负值。阴影变深，色彩更浓，图片看着更扎实。</p>\n<p>照片要放在文字下面时，调暗也有用。调暗的图片能让白色文字看得清，适合幻灯片、海报和社交配图。</p>\n<p>天空太亮、前景太暗的照片，往哪个方向调都修不好。接受折中，或者换一种修法。</p>\n<h2 id=\"noise-and-quality\">噪点、画质与提亮的上限</h2>\n<p>提亮会把噪点带出来。偏暗的照片，颗粒藏在阴影里；亮度一提，颗粒就变成看得见的斑点。</p>\n<p>JPEG 压缩会让问题更严重。偏暗又压缩过的 JPEG，用力提亮后会出现淡淡的块状纹理，因为压缩痕迹也被放大了。</p>\n<p>办法是轻提亮，并且从最好的原图开始。光线好的原图需要提亮的幅度小，提亮幅度小，噪点就少。</p>\n<p>提亮不会改变像素尺寸和分辨率。图片还是原来那么大，变的只是色调，修图本身不会丢细节。</p>\n<h2 id=\"formats-and-export\">格式与导出</h2>\n<p>工具支持 JPG、PNG、WebP、HEIC 等常见图片格式，单个文件最大 20 MB。可以根据需要导出成 JPG、PNG 或者 WebP。</p>\n<p>导出成 PNG 或 WebP 能保留原图的透明部分。如果原图是透明 PNG 图形，提亮后的导出图，通透的地方依然通透。</p>\n<p>照片用高质量 JPG 导出就很好。提亮基本不增加文件大小，导出图和原图重量差不多。</p>\n<p>质量滑块只在 JPG 和 WebP 导出时出现，PNG 导出时没有，因为 PNG 是无损格式，本来就不用调质量。</p>\n<h2 id=\"brightness-and-contrast\">亮度和对比度是一对搭档</h2>\n<p>亮度和对比度是搭档。亮度把整个色调范围一起上下移动，对比度拉大或者压缩明暗两端的距离。</p>\n<p>又暗又平的照片，两个都要调。先提亮，把整体亮度抬起来；再加对比度，把提亮洗掉的深度找回来。</p>\n<p>提亮后图片看着发灰、没精神，就用<a href=\"/zh/tiaozheng-tupian-duibidu/\">图片对比度工具</a>补一点对比。轻轻一推，阴影和高光就回来了。</p>\n<p>两个控制的完整对比，请读<a href=\"/zh/blog/liangdu-puguang-duibidu-qubie/\">亮度、曝光和对比度有什么区别？一文讲清</a>。</p>\n<h2 id=\"privacy-local-processing\">隐私：不用上传就能修亮度</h2>\n<p>所有亮度处理都在浏览器里完成。照片不会上传到任何服务器，处理个人照片、家庭合影或者客户作品时，这一点很重要。</p>\n<p>这比云端修图工具实在得多。一张家庭合影或者私人文件，没必要为了调亮一点就传到看不见的服务器上。</p>\n<p>工具导出时还会清除 EXIF 里的 GPS 信息。下载的提亮照片里，不会留下拍摄地点的记录。</p>\n<p>原图一定要留好。亮度一旦压进导出图，就再也撤不回来了，原图是唯一干净的备份。</p>\n<h2 id=\"common-mistakes\">调亮度最常见的几个错误</h2>\n<p>最常见的错误是提亮太多。推到 +50% 甚至 +100%，高光全没了，照片变成一张又平又白、没有细节的图。</p>\n<p>另一个错误，是已经很亮的照片还要提亮。过曝的照片需要调暗，再加亮只会更糟。</p>\n<p>还有人忘了检查高光。小预览里看着没事的人脸或者天空，放大一看可能已经过曝，所以一定要全尺寸检查。</p>\n<p>最后，别反复用同一张 JPG 改亮度。每保存一次就多一次损伤，想换亮度时，永远回到原图重新做。</p>\n<h2 id=\"brightness-workflow\">一套干净利落的亮度工作流</h2>\n<p>先拿原图，判断要提亮多少。稍微偏暗用 10% 到 15%，很暗的照片可能要 30% 甚至更多。</p>\n<p>调好亮度，看一眼对比视图。分屏能准确显示哪些地方变好了、哪些地方被洗白了。</p>\n<p>提亮后图片看着发平，就补一点对比。轻轻一推，就能把提亮洗掉的深度找回来。</p>\n<p>用高质量设置导出，全尺寸检查一遍。放大看亮部，确认没有细节被提亮提没了。</p>\n<h2 id=\"brightening-for-social\">社交媒体的照片怎么提亮</h2>\n<p>社交信息流喜欢明亮、清晰的照片。偏暗的照片会被直接滑过去，亮度合适的照片才能让人停下来多看一眼。</p>\n<p>社交照片可以比打印照片再亮一点。每个人的屏幕亮度不一样，你手机上看着正好的照片，别人手机上可能偏暗。</p>\n<p>提亮要自然。推得太远，看着很假，关注者一眼就能看出光线和场景对不上。</p>\n<p>发之前先按信息流的尺寸测试一下。全尺寸看着好的照片，缩小到预览尺寸可能太暗或者太亮，先检查再发布。</p>\n<p>想看分步操作，请读<a href=\"/zh/blog/zenme-tiaozheng-tupian-liangdu/\">怎么调图片亮度：5步修好偏暗照片</a>。想看完整对比，请读<a href=\"/zh/blog/liangdu-puguang-duibidu-qubie/\">亮度、曝光和对比度有什么区别？一文讲清</a>；提亮后想补回对比，可以试试<a href=\"/zh/tiaozheng-tupian-duibidu/\">图片对比度工具</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"偏暗的照片应该提亮多少？","answer":"先从 10% 到 15% 开始，看一眼预览。大多数偏暗的照片只需要轻轻一提，幅度再大，高光很快就会被洗白。小步往上加，主体清楚了、高光还没变白的时候就停下来。"},{"question":"为什么提亮后照片看着发灰？","answer":"亮度推得太远了，高光被抬成纯白，亮部的细节全没了。把滑块往回拉，直到天空、皮肤和亮面重新出现纹理。之后再补一点对比度，也能找回深度。"},{"question":"光线很差的时候拍的照片，提亮能救回来吗？","answer":"只能救一部分。提亮能让偏暗的照片看得见，但也会把藏在阴影里的噪点和压缩痕迹带出来。原图底子好的时候轻轻一提效果最好，几乎全黑的照片只靠亮度是救不回来的。"},{"question":"先裁剪还是先调亮度？","answer":"先裁剪，再调亮度。这样你判断亮度的时候，看的是最终构图。先裁掉不需要的暗部，剩下的部分要提亮多少也可能跟着变。"},{"question":"调亮度会改变文件大小吗？","answer":"几乎不会。亮度改的是像素值，不是像素数量，文件大小和原图差不多。真正影响大小的是导出格式和质量设置：高质量 JPG 比低质量 JPG 大得多。"},{"question":"在浏览器工具里提亮私人照片安全吗？","answer":"安全，因为所有处理都在浏览器本地完成，什么都不会上传到服务器。工具导出时还会清除 EXIF 里的 GPS 信息。想保留位置信息或者以后换个亮度再试，记得留好原图。"}];
